def solve(grid):
    import numpy as np
    g = [row[:] for row in grid]
    rows, cols = len(g), len(g[0])
    visited = [[False]*cols for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            if g[r][c] == 5 and not visited[r][c]:
                # flood fill to find rectangle
                sr, sc = r, c
                er, ec = r, c
                stack = [(r,c)]
                visited[r][c] = True
                cells = []
                while stack:
                    cr, cc = stack.pop()
                    cells.append((cr,cc))
                    sr, sc = min(sr,cr), min(sc,cc)
                    er, ec = max(er,cr), max(ec,cc)
                    for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr,nc = cr+dr, cc+dc
                        if 0<=nr<rows and 0<=nc<cols and not visited[nr][nc] and g[nr][nc]==5:
                            visited[nr][nc] = True
                            stack.append((nr,nc))
                # Fill interior with 2
                for ir in range(sr+1, er):
                    for ic in range(sc+1, ec):
                        g[ir][ic] = 2
    return g
